:"Actual completion date"}],"reports":[{"id":"name","label":"Account briefing"},{"id":"companyId","label":"Company"},{"id":"periodStart","label":"Period from"},{"id":"periodEnd","label":"Period to"},{"id":"status","label":"Review state"},{"id":"reviewer","label":"Internal reviewer"}]}};
const CLIENT_CSS=":root{--ct-ink:#112832;--ct-charcoal:#183441;--ct-ink2:#304b58;--ct-lime:#ddf76c;--ct-blue:#478ab7;--ct-sky:#cce9f6;--ct-light:#f6f8f4;--ct-paper:#fff;--ct-border:#d9e0dd;--ct-muted:#60717a;--ct-orange:#a84c2b;--ct-positive:#226849;--ct-shadow:0 10px 28px rgba(14,35,43,.045)}
*{box-sizing:border-box}.ct-app{font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;color:var(--ct-ink);background:var(--ct-light);min-height:100vh;display:grid;grid-template-columns:236px minmax(0,1fr);font-size:14.0px;line-height:1.48}.ct-app button,.ct-app input,.ct-app select,.ct-app textarea{font:inherit}.ct-app button{cursor:pointer}.ct-app button:disabled{cursor:not-allowed;opacity:.46}.ct-app a{color:#165b82;text-decoration:underline;text-underline-offset:3px}.ct-side{height:100vh;position:sticky;top:0;padding:29px 15px 18px;background:#eff3ef;border-right:1px solid #dbe4dd;display:flex;flex-direction:column;min-width:0}.ct-brand-title{padding:3px 10px 20px;font-size:18.0px;font-weight:780;line-height:1.28;letter-spacing:-.5px;white-space:normal;overflow-wrap:anywhere}.ct-side-label{color:#50646c;font-size:12px;font-weight:800;letter-spacing:1.8px;padding:5px 11px 10px}.ct-nav{display:flex;flex-direction:column;gap:6px}.ct-nav-item{display:flex;align-items:center;gap:12px;text-align:left;width:100%;background:transparent;border:0;color:#455e65;padding:12px 12px;border-radius:11px;font-weight:620;font-size:13.0px;line-height:1.2;min-height:43px}.ct-nav-item:hover{background:#e1e9e3;color:#183d40}.ct-nav-item.active{background:#142e38;color:#fff;box-shadow:0 3px 10px #122c3915}.ct-nav-ico{flex:0 0 20px;display:flex;align-items:center}.ct-nav-label{flex:1;min-width:0}.ct-nav-mobile{display:none}.ct-side-bottom{margin-top:auto;padding:14px 6px 0}.ct-layout{background:transparent;border:0;color:#50646c;padding:10px;display:flex;gap:9px;align-items:center;font-size:12px;width:100%;border-radius:10px}.ct-layout:hover{background:#e0e8e2}
.ct-main{min-width:0;padding:34px clamp(18px,3vw,48px) 70px;max-width:1600px;width:100%;margin:0 auto}.ct-pagehead{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:75px;margin-bottom:24px}.ct-pagehead h1{font-size:clamp(24px,2.3vw,31px);letter-spacing:-1.1px;font-weight:750;line-height:1.19;margin:0 0 6px}.ct-pagehead p{margin:0;color:var(--ct-muted);font-size:13.0px}.ct-pageactions{display:flex;align-items:center;gap:8px;flex-shrink:0}.ct-btn{border:1px solid transparent;background:transparent;color:var(--ct-ink);border-radius:10px;display:inline-flex;align-items:center;justify-content:center;gap:7px;padding:10px 14px;font-weight:650;font-size:12px;white-space:nowrap;line-height:1.2;min-height:36px}.ct-btn:hover:not(:disabled){filter:brightness(.96)}.ct-primary{background:var(--ct-ink);color:white;border-color:var(--ct-ink)}.ct-primary:hover:not(:disabled){background:#294452;color:white}.ct-outline{border-color:#cdd9d6;background:white;color:#243e48}.ct-ghost{border-color:transparent;background:transparent;color:#4f656c}.ct-mini{border-color:#d6dedc;background:white;font-size:12px;min-height:28px;padding:6px 9px;border-radius:7px}.ct-link{color:#256f8c;padding-left:4px;padding-right:4px}.ct-on-ink{color:#ddf76c;padding:7px 0}.ct-danger{background:#943c2e;border-color:#943c2e;color:white}.ct-ghost.danger,.ct-mini.danger{background:#fff4f0;border-color:#e5c6bd;color:#91462e}.ct-icon{padding:7px;min-height:34px;width:34px;border-radius:8px}.ct-notice{background:#e8f4ed;border:1px solid #bfd8c7;border-radius:10px;padding:12px 13px;display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:15px;color:#285747;font-size:12px}.ct-notice .ct-icon{flex-shrink:0}.ct-coverage{background:#fff8e8;border:1px solid #e9d7af;padding:11px 15px;border-radius:12px;display:flex;align-items:center;gap:12px;margin-bottom:19px;font-size:12px;color:#70552a;flex-wrap:wrap}.ct-coverage strong{font-weight:750}.ct-coverage small{color:#50646c}.ct-overline{font-size:12px;font-weight:790;letter-spacing:1.5px;color:#50646c}.ct-muted{color:var(--ct-muted);font-size:12px}.ct-panel{background:var(--ct-paper);border:1px solid var(--ct-border);border-radius:14px;padding:20px;box-shadow:var(--ct-shadow);min-width:0}.ct-section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:17px}.ct-section-title h2,.ct-section-title h3{font-size:16.0px;letter-spacing:-.25px;margin:0;font-weight:750;line-height:1.3}.ct-section-title h3{font-size:14.0px}.ct-empty{padding:20px 10px;text-align:center;color:#50646c;font-size:12px}.ct-meta{font-size:12px;color:#50646c}.ct-pill{display:inline-flex;align-items:center;min-height:23px;padding:4px 9px;background:#eef3f2;color:#3f5a62;border:1px solid #dce7e3;border-radius:30px;font-size:12px;font-weight:750;letter-spacing:.1px;line-height:1.1;white-space:nowrap}.ct-pill.accent{background:#e7f49c;border-color:#d4e877;color:#344524}.ct-pill.positive{background:#e5f6e8;border-color:#c5e7cb;color:#266747}.ct-pill.warn{background:#fff0e5;border-color:#f0d0b9;color:#944d26}.ct-external{font-size:12px;font-weight:680}.ct-rowactions{display:flex;gap:4px;align-items:center;justify-content:flex-end;flex-wrap:wrap}.ct-register{margin-top:22px}.ct-table-wrap{overflow-x:auto;max-width:100%;border:1px solid #e2e9e6;border-radius:10px}.ct-table-wrap table{border-collapse:collapse;width:100%;min-width:750px;text-align:left;font-size:12px}.ct-table-wrap th{background:#f1f5f3;color:#50646c;font-size:12px;letter-spacing:.7px;text-transform:uppercase;font-weight:800;padding:12px 11px;white-space:nowrap}.ct-table-wrap td{padding:11px;border-top:1px solid #edf1ef;vertical-align:middle;color:#344c54;max-width:270px;overflow-wrap:anywhere}.ct-table-wrap td:first-child{color:#18333d;font-weight:750;max-width:300px}.ct-table-wrap tbody tr:hover{background:#fcfdfa}.ct-page{display:flex;align-items:center;justify-content:space-between;gap:8px;color:#50646c;font-size:12px;padding:11px 0 0}.ct-page>div{display:flex;gap:2px}.ct-page .ct-btn{font-size:12px;min-height:28px;padding:5px 9px}.ct-source-note{color:#50646c;font-size:12px}.ct-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:17px}.ct-search{flex:1;min-width:0;display:flex;align-items:center;gap:10px;border:1px solid var(--ct-border);background:#fff;border-radius:9px;padding:0 12px;color:#50646c;min-height:42px}.ct-search input{min-width:0;width:100%;border:0;outline:none;font-size:12px;color:var(--ct-ink);background:transparent}.ct-filterpanel{display:flex;gap:15px;align-items:center;margin-bottom:19px;background:#edf3f0;padding:13px 15px;border-radius:12px;flex-wrap:wrap}.ct-filterpanel label{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:650}.ct-filterpanel select,.ct-choose select{border:1px solid #d2dfda;padding:8px 28px 8px 10px;border-radius:8px;background:#fff;color:#27414a;max-width:260px}
/* Sales command desk: signal-first, with a continuous pipeline timeline instead of KPI cards. */
.ct-hero{display:grid;grid-template-columns:1.18fr .9fr;background:var(--ct-ink);color:white;border-radius:16px;overflow:hidden;min-height:260px;box-shadow:0 13px 35px #16364112}.ct-hero-lead{padding:29px 31px;display:flex;flex-direction:column;justify-content:center}.ct-hero-kicker{color:var(--ct-lime);font-size:12px;letter-spacing:1.6px;font-weight:800;display:flex;align-items:center;gap:8px}.ct-pulse-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ct-lime);box-shadow:0 0 0 4px #dcf76c22}.ct-hero-stats{display:flex;align-items:stretch;gap:28px;margin:30px 0 20px}.ct-hero-stats>div{display:flex;flex-direction:column;gap:3px}.ct-hero-stats strong{font-size:clamp(30px,3.7vw,47px);line-height:1.05;letter-spacing:-2px;font-weight:690}.ct-hero-stats span{font-size:12px;color:#50646c}.ct-hero-lead p{margin:0;color:#50646c;font-size:12px;max-width:470px}.ct-hero-spotlight{background:#203a47;padding:26px 28px;border-left:1px solid #38505b;display:flex;flex-direction:column;gap:10px}.ct-hero-spotlight .ct-overline{color:#50646c}.ct-hero-spotlight>b{font-size:23.0px;line-height:1.2;letter-spacing:-.55px;max-width:430px;font-weight:740}.ct-hero-spotlight p{font-size:12px;color:#50646c;line-height:1.6;margin:0;max-width:450px}.ct-hero-foot{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid #466370;padding-top:15px;margin-top:auto}.ct-hero-foot span{font-size:12px;color:#50646c}.ct-two-columns{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:20px}.ct-action-item{background:white;border:0;border-top:1px solid #edf0ef;width:100%;text-align:left;display:flex;align-items:center;gap:12px;padding:12px 0}.ct-action-item:hover{background:#fbfcf8}.ct-date-square{background:#edf4eb;border-radius:8px;padding:8px 9px;min-width:42px;text-align:center;font-size:15.0px;font-weight:780;line-height:1}.ct-date-square small{display:block;color:#50646c;font-size:12px;text-transform:uppercase;margin-top:5px}.ct-action-item>span:nth-child(2){display:flex;flex-direction:column;flex:1;min-width:0}.ct-action-item b{font-size:12px;line-height:1.4}.ct-action-item small{color:#50646c;font-size:12px}.ct-section-foot{font-size:12px;color:#50646c;padding-top:14px}.ct-stage-list{display:flex;flex-direction:column;gap:11px}.ct-pipeline-tick{width:100%;display:grid;grid-template-columns:1fr 28px;gap:5px;align-items:center;background:none;border:0;text-align:left;color:#38515b;padding:0}.ct-pipeline-tick strong{text-align:right;font-size:12px}.ct-tick-head{font-size:12px;font-weight:620}.ct-tick-bar{grid-column:1/3;background:#eef2ef;height:5px;border-radius:9px;overflow:hidden}.ct-tick-bar span{display:block;height:100%;background:var(--ct-blue);border-radius:9px}.ct-stage-footer{padding-top:19px}.ct-account-strip{margin-top:19px}.ct-company-tiles{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.ct-account-tile{display:flex;align-items:flex-start;flex-direction:column;min-height:155px;padding:14px;gap:10px;border:1px solid #e2e8e4;background:#fbfcf9;border-radius:11px;text-align:left;min-width:0}.ct-account-tile:hover{border-color:#a8cbb9;background:#f2f9ee}.ct-account-tile strong{font-size:12px;line-height:1.3}.ct-account-tile small{font-size:12px;color:#50646c;line-height:1.4}.ct-company-mark{width:40px;height:40px;border-radius:11px;background:#dae9e3;color:#234f53;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;flex-shrink:0;letter-spacing:.3px}.ct-company-mark.small{height:37px;width:37px;font-size:12px}.ct-company-mark.big{height:60px;width:60px;font-size:18.0px;border-radius:15px}
/* Account dossier: searchable index and context-rich profile. */
.ct-directory{display:grid;grid-template-columns:minmax(230px,32%) minmax(0,1fr);gap:15px;align-items:stretch}.ct-directory-index{padding:17px 12px;background:#fff;border:1px solid var(--ct-border);border-radius:14px;min-width:0}.ct-directory-index .ct-section-title{margin:0 7px 13px}.ct-company-choice{display:flex;align-items:center;gap:11px;width:100%;text-align:left;padding:10px 9px;border:1px solid transparent;background:transparent;border-radius:10px;color:#18333d}.ct-company-choice:hover{background:#f4f7f2}.ct-company-choice.active{background:#edf5e5;border-color:#d2e4c4}.ct-company-choice-text{display:flex;flex-direction:column;gap:3px;min-width:0;flex:1}.ct-company-choice-text b{font-size:12px;line-height:1.3;white-space:normal}.ct-company-choice-text small{font-size:12px;color:#50646c;line-height:1.4}.ct-company-choice>svg{color:#50646c;flex-shrink:0}.ct-company-profile{background:#fff;border:1px solid var(--ct-border);border-radius:14px;min-width:0;overflow:hidden}.ct-profile-cover{padding:28px 30px 19px;background:#ecf6f0}.ct-profile-heading{display:flex;align-items:center;gap:15px;margin:15px 0}.ct-profile-heading h2{font-size:24.0px;letter-spacing:-.8px;margin:0 0 4px}.ct-profile-heading p{color:#50646c;margin:0;font-size:12px}.ct-profile-pills{display:flex;gap:6px;flex-wrap:wrap}.ct-profile-metrics{display:grid;grid-template-columns:repeat(3,1fr);padding:20px 28px;border-bottom:1px solid #e7ede9}.ct-profile-metrics>div{display:flex;flex-direction:column;gap:2px;padding:0 15px}.ct-profile-metrics>div:first-child{padding-left:0}.ct-profile-metrics>div+div{border-left:1px solid #e7ecea}.ct-profile-metrics b{font-size:25.0px;line-height:1.1}.ct-profile-metrics span{font-size:12px;color:#50646c}.ct-profile-actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:18px}.ct-company-profile>.ct-profile-actions{margin:0;padding:18px 28px}.ct-dossier-chunks{display:grid;grid-template-columns:1fr 1fr;gap:22px;padding:5px 28px 22px}.ct-dossier-chunks h3{font-size:13.0px;font-weight:770;margin:5px 0 15px}.ct-avatar{width:36px;height:36px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;background:#e1ecf2;color:#285c79;font-size:12px;font-weight:800;flex-shrink:0}.ct-avatar.big{width:62px;height:62px;font-size:18.0px}.ct-people-inline{display:flex;align-items:center;gap:9px;padding:7px 0;text-align:left;background:transparent;border:0;width:100%;color:#243f48}.ct-people-inline>span:nth-child(2){display:flex;flex-direction:column;flex:1;min-width:0}.ct-people-inline b{font-size:12px}.ct-people-inline small{font-size:12px;color:#50646c}.ct-evidence-inline{display:flex;flex-direction:column;gap:4px;padding:10px 0;border-bottom:1px solid #edf0ee}.ct-evidence-inline small{font-size:12px;color:#50646c}.ct-evidence-inline b{font-size:12px;line-height:1.35}.ct-profile-source{border-top:1px solid #e7ebe9;padding:15px 28px;color:#50646c;font-size:12px;line-height:1.9}
/* Contact ledger: left document index + focused professional profile. */
.ct-contacts{display:grid;grid-template-columns:minmax(300px,1.04fr) minmax(0,.95fr);gap:18px}.ct-contact-list,.ct-contact-profile{min-height:360px}.ct-contact-item{border:0;border-top:1px solid #edf0ec;background:white;display:flex;align-items:center;text-align:left;gap:11px;width:100%;padding:12px 7px;border-radius:6px}.ct-contact-item:hover,.ct-contact-item.active{background:#f5f9f3}.ct-contact-item>span:nth-child(2){display:flex;flex:1;flex-direction:column;min-width:0}.ct-contact-item strong{font-size:12px}.ct-contact-item small{font-size:12px;color:#50646c}.ct-contact-cover{display:flex;gap:16px;align-items:center;padding:5px 0 20px}.ct-contact-cover h2{margin:5px 0 4px;font-size:22.0px;letter-spacing:-.7px}.ct-contact-cover p{margin:0;font-size:12px;color:#50646c}.ct-contact-flags{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:15px}.ct-details{display:grid;grid-template-columns:minmax(120px,.8fr) 1.2fr;gap:12px;padding:18px 0;border-top:1px solid #e9edeb;border-bottom:1px solid #e9edeb;font-size:12px}.ct-details dt{color:#50646c}.ct-details dd{margin:0;font-weight:650;overflow-wrap:anywhere}.ct-follow-small{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #ecf0ee;padding:9px 0}.ct-follow-small b{font-size:12px}.ct-follow-small small{color:#50646c;font-size:12px}
/* Opportunity pipeline: board is the primary interaction. */
.ct-deal-toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:15px;color:#50646c;font-size:12px}.ct-choose{display:inline-flex;align-items:center;gap:9px;font-size:12px;font-weight:700;color:#4a6369}.ct-board-wrap{border:1px solid #dae5e0;border-radius:14px;background:#eaf0ec;overflow-x:auto;padding:14px;max-width:100%}.ct-board{display:flex;gap:12px;align-items:stretch;min-width:1280px}.ct-lane{width:205px;flex:1;min-width:172px}.ct-lane header{padding:8px 7px 14px;display:flex;align-items:center;gap:8px}.ct-lane header strong{font-size:12px;flex:1}.ct-lane header small{font-size:12px;font-weight:850}.ct-stage-dot{height:9px;width:9px;border-radius:50%;background:#6e9caf}.ct-lane:nth-child(2) .ct-stage-dot{background:#a6ca68}.ct-lane:nth-child(4) .ct-stage-dot{background:#c49a54}.ct-lane:nth-child(5) .ct-stage-dot{background:#b577a1}.ct-lane:nth-child(6) .ct-stage-dot{background:#489879}.ct-lane:nth-child(7) .ct-stage-dot{background:#c98772}.ct-deal-card{display:flex;flex-direction:column;gap:8px;min-height:151px;padding:14px;text-align:left;border:1px solid #e3e9e6;border-radius:10px;background:#fff;margin-bottom:10px;width:100%;color:#18323d;box-shadow:0 3px 13px #213c4210}.ct-deal-card:hover{border-color:#88b5a2;transform:translateY(-1px)}.ct-deal-owner{color:#50646c;font-size:12px;font-weight:760}.ct-deal-card b{font-size:12px;line-height:1.36}.ct-deal-need{font-size:12px;color:#50646c}.ct-deal-bottom{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:5px}.ct-deal-bottom small{font-size:12px;color:#50646c}.ct-lane-more{font-size:12px;color:#50646c;margin:8px}.ct-deal-bottom-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.ct-deal-bottom-grid h3{font-size:16.0px;margin:0 0 7px}.ct-text{font-size:12px;color:#50646c;line-height:1.7}.ct-brief-chips{display:flex;gap:8px;margin:13px 0}.ct-guidance{display:flex;gap:13px;align-items:flex-start;padding:10px 0}.ct-guidance>spa